CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, scope TEXT NOT NULL, stage TEXT NOT NULL, status TEXT NOT NULL, evidence_level TEXT NOT NULL, created_by_role TEXT NOT NULL, created_by_account_id TEXT, authorization_stage TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE enterprises (id TEXT PRIMARY KEY, name TEXT NOT NULL, authorization_status TEXT NOT NULL DEFAULT 'authorized', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '', enterprise_id TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, account_role TEXT NOT NULL DEFAULT 'member');
CREATE TABLE project_memberships (project_id TEXT NOT NULL, account_id TEXT NOT NULL, role TEXT NOT NULL, scope TEXT NOT NULL DEFAULT 'project', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(project_id, account_id));
CREATE TABLE invitations (id TEXT PRIMARY KEY, token TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL, inviter_account_id TEXT NOT NULL, email TEXT NOT NULL, role TEXT NOT NULL, scope TEXT NOT NULL DEFAULT 'project', status TEXT NOT NULL DEFAULT 'pending', expires_at TEXT NOT NULL, accepted_account_id TEXT, idempotency_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id, inviter_account_id, idempotency_key));
CREATE TABLE sessions (token TEXT PRIMARY KEY, account_id TEXT NOT NULL, project_id TEXT, expires_at TEXT NOT NULL, refresh_token TEXT NOT NULL UNIQUE, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE idempotency_records (account_id TEXT NOT NULL, project_id TEXT, action TEXT NOT NULL, request_key TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(account_id, project_id, action, request_key));
CREATE TABLE work_items (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, stage TEXT NOT NULL, status TEXT NOT NULL, assignee_role TEXT NOT NULL, assignee_label TEXT NOT NULL, evidence_completeness INTEGER NOT NULL, blocking_reason TEXT NOT NULL, next_action TEXT NOT NULL, employee_description TEXT NOT NULL DEFAULT '', assignee_account_id TEXT, source_employee_account_id TEXT, employee_draft_json TEXT NOT NULL DEFAULT '{}', material_status TEXT NOT NULL DEFAULT 'undecided', workflow_card_json TEXT NOT NULL DEFAULT '{}', candidate_fact_id TEXT, flow_card_version INTEGER NOT NULL DEFAULT 1, evidence_version INTEGER NOT NULL DEFAULT 1, assigned_verifier_id TEXT, assignment_version INTEGER NOT NULL DEFAULT 1, submission_version INTEGER NOT NULL DEFAULT 0, submitted_at TEXT, handoff_status TEXT NOT NULL DEFAULT 'not_submitted', last_submission_key TEXT, evidence_json TEXT NOT NULL DEFAULT '[]', alternative_explanations_json TEXT NOT NULL DEFAULT '[]', judgment_status TEXT NOT NULL DEFAULT 'open', supplement_id TEXT, revision_reason TEXT, revision_from_version INTEGER, revision_packet_id TEXT, FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL, work_item_id TEXT, type TEXT NOT NULL, actor_role TEXT NOT NULL, actor_id TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, contract_version TEXT, run_id TEXT, member_id TEXT, role TEXT, version INTEGER, reason TEXT, source_refs TEXT, authorization TEXT, idempotency_key TEXT, FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE fact_judgments (id TEXT PRIMARY KEY, work_item_id TEXT NOT NULL, fact_id TEXT NOT NULL, decision TEXT NOT NULL, reason TEXT NOT NULL, correction TEXT, source_refs TEXT NOT NULL, actor_id TEXT NOT NULL, flow_card_version INTEGER NOT NULL, evidence_version INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE evidence_supplements (id TEXT PRIMARY KEY, work_item_id TEXT NOT NULL, fact_id TEXT NOT NULL, requested_material TEXT NOT NULL, responsible_person TEXT NOT NULL, responsible_account_id TEXT, deadline TEXT NOT NULL, recovery_entry TEXT NOT NULL, authorization_scope TEXT NOT NULL, source_refs TEXT NOT NULL, old_evidence_version INTEGER NOT NULL, new_evidence_version INTEGER NOT NULL, status TEXT NOT NULL, material TEXT, material_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, provided_at TEXT);
CREATE TABLE enterprise_authorizations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, name TEXT NOT NULL, authorizer_name TEXT NOT NULL, authorizer_email TEXT NOT NULL, scope TEXT NOT NULL, reference TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_by_account_id TEXT NOT NULL, creation_idempotency_key TEXT NOT NULL, confirmation_token_nonce TEXT NOT NULL, confirmation_token_hash TEXT NOT NULL, confirmation_token_expires_at TEXT NOT NULL, token_consumed_at TEXT, confirmation_delivery_status TEXT NOT NULL DEFAULT 'pending', confirmation_delivery_attempts INTEGER NOT NULL DEFAULT 0, confirmation_delivery_last_error TEXT, confirmation_delivery_last_attempt_at TEXT, confirmed_by_identity TEXT, confirmed_at TEXT, confirmation_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE authorization_notification_outbox (notification_id TEXT PRIMARY KEY, authorization_id TEXT NOT NULL, project_id TEXT NOT NULL, token_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', dispatch_attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(authorization_id, token_hash), FOREIGN KEY (authorization_id) REFERENCES enterprise_authorizations(id));
CREATE TABLE evidence_materials (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, material_key TEXT NOT NULL, version INTEGER NOT NULL, previous_version_id TEXT, source_type TEXT NOT NULL, authorization_record_id TEXT, authorization_status TEXT NOT NULL DEFAULT 'pending', integrity_status TEXT NOT NULL DEFAULT 'pending', visibility TEXT NOT NULL DEFAULT 'project', created_by_account_id TEXT NOT NULL, work_item_id TEXT, label TEXT NOT NULL, reference TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', reviewed_by_account_id TEXT, reviewed_at TEXT, review_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id, material_key, version), FOREIGN KEY (project_id) REFERENCES projects(id), FOREIGN KEY (authorization_record_id) REFERENCES enterprise_authorizations(id), FOREIGN KEY (previous_version_id) REFERENCES evidence_materials(id));
CREATE TABLE candidate_facts (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, work_item_id TEXT NOT NULL, fact_type TEXT NOT NULL, claim TEXT NOT NULL, source_field TEXT NOT NULL, required INTEGER NOT NULL DEFAULT 1, impact_level TEXT NOT NULL DEFAULT 'normal', second_confirmation_status TEXT NOT NULL DEFAULT 'not_required', material_status TEXT NOT NULL DEFAULT 'unverified', status TEXT NOT NULL DEFAULT 'open', correction TEXT, source_refs_json TEXT NOT NULL DEFAULT '[]', first_verified_by_account_id TEXT, verified_by_account_id TEXT, last_transition_key TEXT, flow_card_version INTEGER NOT NULL DEFAULT 1, evidence_version INTEGER NOT NULL DEFAULT 1, evidence_level TEXT, evidence_level_source TEXT, evidence_labeled INTEGER NOT NULL DEFAULT 0, evidence_level_updated_at TEXT, evidence_level_updated_by_account_id TEXT, impact_level_updated_at TEXT, impact_level_updated_by_account_id TEXT, impact_level_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, verified_at TEXT, FOREIGN KEY (project_id) REFERENCES projects(id), FOREIGN KEY (work_item_id) REFERENCES work_items(id));
CREATE TABLE fact_second_confirmations (id TEXT PRIMARY KEY, fact_id TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL, work_item_id TEXT NOT NULL, first_verifier_account_id TEXT NOT NULL, confirmer_type TEXT NOT NULL, confirmer_identity TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (fact_id) REFERENCES candidate_facts(id), FOREIGN KEY (project_id) REFERENCES projects(id), FOREIGN KEY (work_item_id) REFERENCES work_items(id));
CREATE TABLE decision_packets (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, version INTEGER NOT NULL, status TEXT NOT NULL, drafted_by_account_id TEXT NOT NULL, verifier_account_id TEXT, fact_refs_json TEXT NOT NULL, risk_summary TEXT NOT NULL, pilot_scope TEXT NOT NULL, constraints_json TEXT NOT NULL, success_metrics_json TEXT NOT NULL, stop_conditions_json TEXT NOT NULL, downstream_owner TEXT NOT NULL, last_transition_key TEXT, revision_reason TEXT, revision_from_version INTEGER, revision_work_item_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, verified_at TEXT, published_at TEXT, UNIQUE(project_id, version), FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE owner_decisions (id TEXT PRIMARY KEY, packet_id TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL, owner_account_id TEXT NOT NULL, decision TEXT NOT NULL, reason TEXT NOT NULL, scope TEXT NOT NULL, constraints_json TEXT NOT NULL, success_metrics_json TEXT NOT NULL, stop_conditions_json TEXT NOT NULL, downstream_owner TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (packet_id) REFERENCES decision_packets(id), FOREIGN KEY (project_id) REFERENCES projects(id));
CREATE TABLE member_login_challenges (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, consumed_at TEXT, consume_claim TEXT UNIQUE, delivery_status TEXT NOT NULL DEFAULT 'pending', delivery_error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (account_id) REFERENCES accounts(id));
CREATE INDEX idx_work_items_project_stage ON work_items(project_id, stage);
CREATE INDEX idx_events_project_created ON events(project_id, id);
CREATE INDEX idx_decision_packets_project_version ON decision_packets(project_id, version DESC);
CREATE INDEX idx_authorizations_project_status ON enterprise_authorizations(project_id, status);
CREATE UNIQUE INDEX idx_authorization_creation_idempotency ON enterprise_authorizations(project_id, created_by_account_id, creation_idempotency_key);
CREATE INDEX idx_authorization_outbox_status ON authorization_notification_outbox(status, updated_at);
CREATE INDEX idx_materials_project_visibility ON evidence_materials(project_id, visibility, authorization_status, integrity_status);
CREATE UNIQUE INDEX idx_material_versions_unique ON evidence_materials(project_id, material_key, version);
CREATE INDEX idx_candidate_facts_item_status ON candidate_facts(work_item_id, status);
CREATE INDEX idx_candidate_facts_evidence_level ON candidate_facts(project_id, evidence_level);
CREATE INDEX idx_second_confirmations_project ON fact_second_confirmations(project_id, created_at);
CREATE UNIQUE INDEX idx_revision_task_packet ON work_items(revision_packet_id) WHERE revision_packet_id IS NOT NULL;
CREATE INDEX idx_projects_authorization_stage ON projects(authorization_stage);
CREATE INDEX idx_member_login_challenges_account_created ON member_login_challenges(account_id, created_at DESC);
CREATE INDEX idx_member_login_challenges_expiry ON member_login_challenges(expires_at, consumed_at);
